def transform(wb):
    ws = wb['Sheet1']
    result_values = []
    for r in range(5, 20):
        v = ws.cell(row=r, column=4).value
        if v is not None:
            result_values.append(v)
    rows = []
    for r in range(3, 22):
        a = ws.cell(row=r, column=1).value
        b = ws.cell(row=r, column=2).value
        rows.append((a, b))
    remove_indices = []
    removed_values = []
    for rv in result_values:
        if rv in removed_values:
            continue
        for i in range(len(rows)):
            if i not in remove_indices and rows[i][0] == rv:
                remove_indices.append(i)
                removed_values.append(rv)
                break
    kept = []
    for i in range(len(rows)):
        if i not in remove_indices:
            kept.append(rows[i])
    for i in range(19):
        r = i + 3
        if i < len(kept):
            ws.cell(row=r, column=1).value = kept[i][0]
            ws.cell(row=r, column=2).value = kept[i][1]
        else:
            ws.cell(row=r, column=1).value = None
            ws.cell(row=r, column=2).value = None
    ws.cell(row=2, column=8).value = '=SUM(A3:A21)'
    return None
